<?php

if(PHP_SAPI!=='cli'){http_response_code(403);exit(1);}
define('NOLOGIN',1);define('NOREQUIREMENU',1);define('NOREQUIREHTML',1);define('NOCSRFCHECK',1);
$documentRoot=getenv('M062_DOL_DOCUMENT_ROOT');if(!$documentRoot)$documentRoot='/Users/mac/Documents/dev/dolibarr/dolibarr-Dev/dolibarr-23.0.3/htdocs';
$_SERVER['DOCUMENT_ROOT']=$documentRoot;$_SERVER['SERVER_NAME']='127.0.0.1';$_SERVER['SERVER_PORT']='8088';require $documentRoot.'/master.inc.php';
$root=dirname(__DIR__,2);require_once $root.'/custom/chinaplanetshippingprices/class/PortNameResolver.class.php';
function m062dataAssert($condition,$message){if(!$condition)throw new RuntimeException($message);}global$db,$conf;$entity=(int)$conf->entity;
function m062dataOne($db,$sql){$res=$db->query($sql);if(!$res)throw new RuntimeException('Current-data query failed.');return$db->fetch_object($res);}
$summary=m062dataOne($db,"SELECT COUNT(*) total,COALESCE(SUM(destination_country IS NULL OR destination_country=''),0) unmapped,COALESCE(SUM(port_match_method='composite'),0) composite,COALESCE(SUM(pod_raw IS NOT NULL AND pod_raw<>pod),0) normalized FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity);
m062dataAssert((int)$summary->unmapped===0,'Current rates still contain unmapped destinations.');
$aliases=m062dataOne($db,"SELECT COUNT(*) total,COUNT(DISTINCT normalized_alias) unique_total FROM ".MAIN_DB_PREFIX."chinaplanetsp_port_alias WHERE entity=".$entity." AND status=1");
m062dataAssert((int)$aliases->total===(int)$aliases->unique_total&&(int)$aliases->total>0,'Active normalized aliases are duplicated or missing.');
$resolver=new PortNameResolver($db,$entity);
$catalogAliases=0;foreach(PortNameResolver::catalog()as$definition){foreach(array_merge(array($definition['port_name']),$definition['aliases'])as$alias){if(PortNameResolver::normalize($alias)==='')continue;$catalogAliases++;$match=$resolver->resolveList($alias,false);m062dataAssert($match['status']==='matched'&&count($match['matches'])===1&&$match['matches'][0]['port_name']===$definition['port_name']&&$match['matches'][0]['country_code']===$definition['country_code'],'Catalog alias failed for '.$alias);}}
m062dataAssert((int)$aliases->total>=$catalogAliases,'Active alias table does not contain the complete catalog.');
$validatedCompositeValues=0;$rawResult=$db->query("SELECT DISTINCT pod_raw FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity." AND pod_raw IS NOT NULL AND pod_raw<>''");if(!$rawResult)throw new RuntimeException('Composite audit query failed.');while($raw=$db->fetch_object($rawResult)){$resolution=$resolver->resolveList($raw->pod_raw,true);if($resolution['status']!=='matched'||count($resolution['matches'])<2)continue;$validatedCompositeValues++;foreach($resolution['matches']as$match){$row=m062dataOne($db,"SELECT COUNT(*) total FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity." AND pod_raw='".$db->escape($raw->pod_raw)."' AND pod='".$db->escape($match['port_name'])."' AND destination_country='".$db->escape($match['country_code'])."' AND port_match_method='composite'");m062dataAssert((int)$row->total>0,'Composite destination missing for '.$raw->pod_raw.' -> '.$match['port_name']);}}
$destinationWarnings=0;$otherWarnings=0;$res=$db->query("SELECT rowid,warning_count,report_json FROM ".MAIN_DB_PREFIX."chinaplanetsp_batch WHERE entity=".$entity);while($batch=$db->fetch_object($res)){$report=json_decode((string)$batch->report_json,true);$warnings=is_array($report)&&isset($report['warnings'])&&is_array($report['warnings'])?$report['warnings']:array();foreach($warnings as$warning){if(preg_match('/^(?:Unmapped|Ambiguous) destination/u',$warning))$destinationWarnings++;else$otherWarnings++;}}
m062dataAssert($destinationWarnings===0,'Resolved destination warnings remain in batch reports.');
$cloneDuplicates=m062dataOne($db,"SELECT COUNT(*) total FROM (SELECT fk_batch,source_row,COALESCE(source_cell,'') source_cell,pod,container_type,shipping_line,cost_price,COUNT(*) copies FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity." AND port_match_method='composite' GROUP BY fk_batch,source_row,COALESCE(source_cell,''),pod,container_type,shipping_line,cost_price HAVING COUNT(*)>1) duplicate_composites");
m062dataAssert((int)$cloneDuplicates->total===0,'Composite migration created duplicate destination rows.');
print 'OK M062 current data rates='.(int)$summary->total.' unmapped=0 composite='.(int)$summary->composite.' composite_values='.$validatedCompositeValues.' normalized='.(int)$summary->normalized.' aliases='.(int)$aliases->total.' destination_warnings=0 other_warnings='.$otherWarnings."\n";
